package com.campusiq.platform.service;
import com.campusiq.common.exception.ApiException; import com.campusiq.platform.dto.*; import com.campusiq.platform.entity.*; import com.campusiq.platform.repository.*; import com.campusiq.platform.strategy.*; import com.campusiq.user.repository.UserRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class PlatformService {private final UserRepository users; private final UserPlatformAccountRepository accounts; private final PlatformStatSnapshotRepository snapshots; private final PlatformStrategyFactory strategies; public PlatformService(UserRepository u,UserPlatformAccountRepository a,PlatformStatSnapshotRepository s,PlatformStrategyFactory f){users=u;accounts=a;snapshots=s;strategies=f;} @Transactional public PlatformProfileResponse connect(Long userId,ConnectPlatformRequest request){var strategy=strategies.get(request.platform());if(!strategy.verifyUser(request.username()))throw new ApiException(HttpStatus.BAD_REQUEST,"Username does not exist on "+request.platform());return saveFetchedProfile(userId,request.platform(),strategy.fetchProfile(request.username()));} @Transactional public PlatformProfileResponse sync(Long userId,Platform platform){var account=accounts.findByUserIdAndPlatform(userId,platform).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Platform account not found"));var strategy=strategies.get(platform);return saveFetchedProfile(userId,platform,strategy.fetchProfile(account.getUsername()));} private PlatformProfileResponse saveFetchedProfile(Long userId,Platform platform,PlatformProfileResponse profile){if(profile==null||profile.username()==null||profile.username().isBlank())throw new ApiException(HttpStatus.BAD_GATEWAY,"Platform returned an incomplete profile");var account=accounts.findByUserIdAndPlatform(userId,platform).orElseGet(UserPlatformAccount::new);account.setUser(users.getReferenceById(userId));account.setPlatform(platform);account.setUsername(profile.username());account.setStatus(AccountStatus.VERIFIED);account.setVerifiedAt(account.getVerifiedAt()==null?Instant.now():account.getVerifiedAt());account.setLastSyncedAt(Instant.now());account=accounts.save(account);var snapshot=snapshots.findByAccountId(account.getId()).orElseGet(PlatformStatSnapshot::new);snapshot.setAccount(account);snapshot.updateFrom(profile.ranking(),profile.totalSolved(),profile.easySolved(),profile.mediumSolved(),profile.hardSolved(),profile.contestRating(),profile.contestRanking(),profile.contestTopPercent(),profile.currentRating(),profile.maxRating(),profile.codingScore(),profile.currentStreak(),profile.maxStreak(),profile.countryRank(),profile.stars(),profile.toString());snapshots.save(snapshot);return profile;} public List<PlatformAccountResponse> accounts(Long userId){return accounts.findAllByUserId(userId).stream().map(PlatformAccountResponse::from).toList();} public PlatformProfileResponse storedProfile(Long userId,Platform platform){var a=accounts.findByUserIdAndPlatform(userId,platform).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Platform account not found"));var s=snapshots.findByAccountId(a.getId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"No stored statistics found"));String url=switch(platform){case LEETCODE->"https://leetcode.com/u/"+a.getUsername()+"/";case CODEFORCES->"https://codeforces.com/profile/"+a.getUsername();case CODECHEF->"https://www.codechef.com/users/"+a.getUsername();case GEEKSFORGEEKS->"https://www.geeksforgeeks.org/user/"+a.getUsername()+"/";};return new PlatformProfileResponse(platform,a.getUsername(),url,null,null,s.getGlobalRank(),null,s.getProblemsSolved(),s.getEasySolved(),s.getMediumSolved(),s.getHardSolved(),s.getContestRating(),s.getContestRanking(),s.getContestTopPercent(),s.getCurrentRating(),s.getMaxRating(),s.getCodingScore(),s.getCurrentStreak(),s.getMaxStreak(),s.getCountryRank(),s.getStars());}}
